input.sparql:
SELECT ?z ?lbl WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?lbl .
  FILTER(CONTAINS(?lbl, "ZN_4"))
}

SELECT ?p ?class WHERE {
  ?p a brick:AirTemperatureSensor .
  ?p ?class ?v .
  FILTER(?class = rdfs:label)
}

SELECT ?p ?lbl WHERE {
  ?p a brick:Air_Temperature_Sensor .
  OPTIONAL{?p rdfs:label ?lbl}
}

SELECT ?p ?ts ?tsid WHERE {
  ?z a brick:HVAC_Zone .
  ?z rdfs:label "Perimeter_mid_ZN_4" .
  ?z brick:hasPoint ?p .
  ?p a brick:Zone_Air_Temperature_Sensor .
  OPTIONAL{?p ref:hasExternalReference ?ts}
  OPTIONAL{?p ref:hasTimeseriesId ?tsid}
}
